-- Sumdoku (`sumdoku@1`): the 6×6 Sudoku with cages, verified by the database.
--
-- Fill a 6×6 grid so every row, every column and every 2×3 box holds 1 to 6 once
-- each, and the digits in every cage add up to its total with no repeats. Boards
-- come from a bank of unique cage puzzles, turned by a seeded mirror, and a run has
-- no clock to lose to: like `mini-sudoku@2`, every board has a par time and a run
-- ahead of its par earns a speed bonus (`public.speed_bonus`), measured by the
-- server from the session's start.
--
-- This migration adds the rules, the puzzle bank, the board draw, the verifier
-- (`complete_sumdoku_run`), the (`sumdoku`, `sumdoku@1`) row in
-- `public.game_runtimes`, and the rules version in `public.run_resumable`. Nothing a
-- user can see changes: `20261221120100_sumdoku_playable.sql` flips the catalogue
-- and lands last, once the service that routes `sumdoku@` runs to the new verifier
-- and the client that plays it are deployed. Mirrored by src/lib/games/sumdoku.ts;
-- the boards in tests/security/verifier_vectors.sql pin the two together. See
-- docs/games/README.md.

-- ─────────────────────────────────────────────────────────────────────────────
-- The rules, as constants the database owns
-- ─────────────────────────────────────────────────────────────────────────────

create or replace function public.sumdoku_rules_version()
returns text language sql immutable set search_path = '' as $$ select 'sumdoku@1'::text $$;

create or replace function public.sumdoku_max_actions()
returns integer language sql immutable set search_path = '' as $$ select 8192 $$;

comment on function public.sumdoku_rules_version() is
  'The Sumdoku rules version new runs pin: sumdoku@1.';
comment on function public.sumdoku_max_actions() is
  'The most moves one Sumdoku submission may carry: a request ceiling, not a final board.';

-- ─────────────────────────────────────────────────────────────────────────────
-- The puzzle bank: four tiers of 30 unique cage puzzles
-- ─────────────────────────────────────────────────────────────────────────────
--
-- A puzzle is 108 characters in three blocks of 36, reading order: the solution
-- (1–6), each cell's cage (base 36) and the givens (1 filled, 0 empty). The verifier
-- reads the first and last blocks; the cages are the client's to draw.

