comment on function public.sumdoku_bank() is
  'The sumdoku@1 puzzle bank: four tiers of 30 unique cage puzzles (solution, cages, givens; 108 characters each). Mirrored by src/lib/games/sumdoku-bank.ts.';

-- The tier a level's board is drawn from: 0 gentle, 1 easy, 2 medium, 3 hard.
create or replace function public.sumdoku_tier(p_level integer)
returns integer
language plpgsql
immutable
set search_path = ''
as $$
begin
  if p_level is null or p_level < 1 then
    raise exception 'a Sumdoku level is one or more' using errcode = '22023';
  end if;
  return case when p_level <= 2 then 0 when p_level <= 5 then 1 when p_level <= 9 then 2 else 3 end;
end;
$$;

-- The par of the first `p_cleared` boards: 75, 90, 120 and 150 s by tier.
create or replace function public.sumdoku_par_ms(p_cleared integer)
returns bigint
language plpgsql
immutable
set search_path = ''
as $$
declare
  v_total bigint := 0;
  v_level integer;
begin
  for v_level in 1..greatest(coalesce(p_cleared, 0), 0) loop
    v_total := v_total + case public.sumdoku_tier(v_level)
      when 0 then 75000 when 1 then 90000 when 2 then 120000 else 150000
    end;
  end loop;
  return v_total;
end;
$$;

comment on function public.sumdoku_tier(integer) is
  'The bank tier a Sumdoku level draws from: boards 1–2 gentle (0), 3–5 easy (1), 6–9 medium (2), then hard (3).';
comment on function public.sumdoku_par_ms(integer) is
  'The par time of the first n Sumdoku boards: 75, 90, 120 and 150 seconds a board by tier.';

revoke all on function public.sumdoku_par_ms(integer) from public;

-- ─────────────────────────────────────────────────────────────────────────────
-- A board: a bank puzzle, mirrored
-- ─────────────────────────────────────────────────────────────────────────────
--
-- One Move's outer LCG advanced once per level, and a second LCG started at that
-- state, as every endless puzzle draws. Two draws, in this order:
--
--   1. the puzzle: entry draw() mod 30 of the level's tier;
--   2. the mirror: draw() mod 4 — bit 1 turns the grid top to bottom, bit 2 left
--      to right.
--
-- The board's cell (r, c) is the puzzle's cell (r', c'), with r' = 5 − r when
-- turned top to bottom and c' = 5 − c when turned left to right. Returns 72
-- values: the starting cells (0 empty), then the solution.

create or replace function public.sumdoku_board(
  p_seed  bigint,
  p_level integer
)
returns integer[]
language plpgsql
immutable
set search_path = ''
as $$
declare
  v_state    bigint;
  v_current  integer;
  v_puzzle   text;
  v_mirror   integer;
  v_row      integer;
  v_column   integer;
  v_from     integer;
  v_digit    integer;
  v_start    integer[] := array[]::integer[];
  v_solution integer[] := array[]::integer[];
begin
  if p_seed is null then
    raise exception 'a seed is required' using errcode = '22023';
  end if;
  if p_level is null or p_level < 1 or p_level > 8192 then
    raise exception 'sumdoku level is outside the reachable run' using errcode = '22023';
  end if;

  v_state := (p_seed % 4294967296 + 4294967296) % 4294967296;
  if v_state = 0 then
    v_state := 2654435769; -- 0x9E3779B9: a zero state would make the sequence degenerate
  end if;
  for v_current in 1..p_level loop
    v_state := (v_state * 1664525 + 1013904223) % 4294967296;
  end loop;

  -- 1. The puzzle.
  v_state := (v_state * 22695477 + 1) % 4294967296;
  v_puzzle := (public.sumdoku_bank())[public.sumdoku_tier(p_level) * 30 + ((v_state >> 16) % 30)::integer + 1];

  -- 2. The mirror.
  v_state := (v_state * 22695477 + 1) % 4294967296;
  v_mirror := ((v_state >> 16) % 4)::integer;

  for v_row in 0..5 loop
    for v_column in 0..5 loop
      v_from := (case when v_mirror & 1 <> 0 then 5 - v_row else v_row end) * 6
              + (case when v_mirror & 2 <> 0 then 5 - v_column else v_column end);
      v_digit := substr(v_puzzle, v_from + 1, 1)::integer;
      v_solution := v_solution || v_digit;
      v_start := v_start || case when substr(v_puzzle, 72 + v_from + 1, 1) = '1'
                                 then v_digit else 0 end;
    end loop;
  end loop;

  return v_start || v_solution;
end;
$$;

comment on function public.sumdoku_board(bigint, integer) is
  'A sumdoku@1 board: its starting cells (36 values, 0 empty) then its solution (36 values), from the level''s bank tier, mirrored by the seed. Mirrored by src/lib/games/sumdoku.ts.';

revoke all on function public.sumdoku_board(bigint, integer) from public;

-- ─────────────────────────────────────────────────────────────────────────────
-- Complete a run: replay, verify, then record
-- ─────────────────────────────────────────────────────────────────────────────
--
-- A move is `cell × 10 + digit`: it names a cell that did not start filled and
-- sets it to the digit, 0 clearing it. A cell that started filled, a cell off the
-- board, a digit above 6, or a move that leaves the cell as it was is impossible
-- play. A board is solved once its cells are its solution — every puzzle has
-- exactly one, so that is the same as full and within the rules — and scores sixty
-- points before the next starts. A submission that stops with the run live is the
-- player ending it, and is valid: the score never goes down. The claim is the
-- points before the bonus; `speed_run_finish` adds the bonus by the server's time.

create or replace function public.complete_sumdoku_run(
  p_session_id  uuid,
  p_actions     integer[],
  p_score       bigint,
  p_duration_ms integer
)
returns public.play_result
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_gate     record;
  v_result   public.play_result;
  v_board    integer[];
  v_start    integer[];
  v_solution integer[];
  v_cells    integer[];
  v_level    integer := 1;
  v_score    bigint := 0;
  v_cleared  integer := 0;
  v_placed   integer := 0;
  v_action   integer;
  v_cell     integer;
  v_digit    integer;
begin
  select * into v_gate from public.speed_run_gate(
    p_session_id, p_actions, p_score, p_duration_ms,
    public.sumdoku_rules_version(), public.sumdoku_max_actions());
  if (v_gate.refusal).outcome is not null then
    return v_gate.refusal;
  end if;

  v_result.session_id := (v_gate.session).id;
  v_result.game_slug := (v_gate.game).slug;

  v_board := public.sumdoku_board((v_gate.session).seed, v_level);
  v_start := v_board[1:36];
  v_solution := v_board[37:72];
  v_cells := v_start;

  foreach v_action in array p_actions loop
    v_cell := v_action / 10;
    v_digit := v_action % 10;
    if v_action < 0 or v_cell > 35 or v_digit > 6
       or v_start[v_cell + 1] <> 0 or v_cells[v_cell + 1] = v_digit then
      v_result.outcome := 'invalid_actions';
      return v_result;
    end if;

    v_cells[v_cell + 1] := v_digit;
    v_placed := v_placed + 1;

    if v_cells = v_solution then
      v_cleared := v_cleared + 1;
      v_score := v_score + 60;
      v_level := v_level + 1;
      v_board := public.sumdoku_board((v_gate.session).seed, v_level);
      v_start := v_board[1:36];
      v_solution := v_board[37:72];
      v_cells := v_start;
    end if;
  end loop;

  if p_score is distinct from v_score then
    v_result.outcome := 'score_mismatch';
    v_result.score := v_score;
    return v_result;
  end if;

  return public.speed_run_finish(
    v_gate.session, v_gate.game, v_gate.digest, v_score,
    public.sumdoku_par_ms(v_cleared), v_gate.elapsed,
    v_cleared, v_placed, p_duration_ms);
end;
$$;

comment on function public.complete_sumdoku_run(uuid, integer[], bigint, integer) is
  'Replays a Sumdoku run from the session''s seed, adds the speed bonus by the server''s own time, and records it. The caller identity is the verified token; the claim is the points before the bonus, compared and never trusted.';

revoke all on function public.complete_sumdoku_run(uuid, integer[], bigint, integer) from public;
grant execute on function public.complete_sumdoku_run(uuid, integer[], bigint, integer) to anon, authenticated;

-- ─────────────────────────────────────────────────────────────────────────────
-- The start gate and saved runs learn Sumdoku
-- ─────────────────────────────────────────────────────────────────────────────

insert into public.game_runtimes (runtime, rules_version, max_actions, session_hours)
values ('sumdoku', public.sumdoku_rules_version(), public.sumdoku_max_actions(), 12)
on conflict (runtime, rules_version) do update
  set max_actions   = excluded.max_actions,
      session_hours = excluded.session_hours;

create or replace function public.run_resumable(p_rules_version text)
returns boolean
language sql
immutable
set search_path = ''
as $$
  select coalesce(p_rules_version in (
    'stack-10@2', 'chain@2', 'memory-flash@2', 'one-move@2', 'color-merge@2',
    'queens@1', 'queens@2',
    'gridburst@1',
    'zip@2', 'eight-puzzle@2', 'tango@2',
    'sudoku@3', 'sudoku@4', 'mini-sudoku@1', 'mini-sudoku@2', 'decant@2',
    'bolted@1', 'huedini@1', 'scatter@1', 'cascade@1', 'checkmate@1', 'fusebox@1',
    'minefield@1', 'sumdoku@1'
  ), false)
$$;
